import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) {
        // 1. 일꾼 3명이 대기하는 사무소 건설
        ExecutorService office = Executors.newFixedThreadPool(3);

        // 2. 사무소에 일감을 던짐
        office.execute(() -> System.out.println("A 작업 처리 중..."));
        office.execute(() -> System.out.println("B 작업 처리 중..."));

        // 3. 사무소 문을 닫음
        office.shutdown();
    }
}
